import json
from pathlib import Path
qs=[json.loads(x) for x in Path('questions.jsonl').read_text().splitlines() if x.strip()]
print('QUESTION_COUNT',len(qs))
for q in qs: print(json.dumps(q,ensure_ascii=False))
print('RECORD_FILES')
for p in sorted(Path('records').rglob('*')):
 if p.is_file(): print(str(p),p.stat().st_size)
