/bin/bash -lc "python3 - <<'PY'
import json,re
with open('records/phase-1/tdocs.jsonld') as f: g=json.load(f)['@graph']
d={r['@id']:r for r in g}; del g
with open('records/phase-4/crpacks.jsonld') as f: g=json.load(f)['@graph']
refs={x for r in g for x in (r['hasCR'] if isinstance(r['hasCR'],list) else [r['hasCR']])}
print('PACK_MEMBERS_MISSING_TDOC',sorted(refs-d.keys()))
with open('records/phase-4/section_extensions.jsonld') as f: g=json.load(f)['@graph']
refs={x for r in g for x in (r['modifiedByCR'] if isinstance(r['modifiedByCR'],list) else [r['modifiedByCR']])}
print('SECTION_CR_MISSING_TDOC',sorted(refs-d.keys()))
for id in ['tdoc:R3-184262','tdoc:R3-194588','tdoc:R3-204387']:
 print('DOC',json.dumps(d.get(id)))
with open('records/phase-4/cr_extensions.jsonld') as f: g=json.load(f)['@graph']
for r in g:
 if r['@id']=='tdoc:R3-184262': print('EXT',json.dumps(r))
PY"

